182	func compactJSONLWith(content []byte, opts MetadataFields, preprocess linePreprocessor) ([]byte, error) {
183		base := newTranscriptLine(opts)
184	
185		// Pass 1: parse all lines into intermediate entries.
186		entries, err := parseJSONLEntries(content, preprocess)
187		if err != nil {
188			return nil, err
189		}
190	
191		// Pass 2: merge and emit.
192		var result []byte
193		for i := 0; i < len(entries); i++ {
194			e := entries[i]
195	
196			switch e.kind {
197			case transcript.TypeAssistant:
198				// Merge consecutive assistant entries with the same message ID.
199				merged := e
200				for i+1 < len(entries) && entries[i+1].kind == transcript.TypeAssistant && entries[i+1].id == e.id {
201					i++
202					merged = mergeAssistantEntries(merged, entries[i])
203				}
204	
205				// Look ahead for user tool_result entries to inline.
206				if i+1 < len(entries) && entries[i+1].kind == transcript.TypeUser && hasToolResults(entries[i+1]) {
207					userEntry := entries[i+1]
208					merged = inlineToolResults(merged, userEntry)
209					i++ // consume the user tool_result entry
210	
211					// If the consumed user entry also had text or image content, emit it
212					// as a separate user line after the assistant.
213					if userEntry.userText != "" || len(userEntry.userImages) > 0 {
214						emitAssistant(&result, base, merged)
215						emitUser(&result, base, userEntry)
216						continue
217					}
218				}
219	
220				if isEmptyContentArray(merged.content) {
221					continue
222				}
223	
224				emitAssistant(&result, base, merged)
225	
226			case transcript.TypeUser:
227				// User entries that are purely tool results were already consumed
228				// by the assistant look-ahead above. If we reach one here it was
229				// not preceded by an assistant with a matching tool_use, so emit
230				// it only if it has text or image content.
231				if hasToolResults(e) && e.userText == "" && len(e.userImages) == 0 {
232					continue
233				}
234				emitUser(&result, base, e)
235			}
236		}
237	
238		return result, nil
239	}
