495	// enrichToolResults extracts structured metadata from a toolUseResult envelope
496	// and attaches it to the corresponding tool result entries.
497	//
498	// Claude Code's toolUseResult has different shapes per tool:
499	//   - Bash:  {stdout, stderr, interrupted, ...}
500	//   - Read:  {type:"text", file:{filePath, numLines, content, ...}}
501	//   - Grep:  {numFiles, numLines, filenames, content, mode}
502	//   - Edit:  {filePath, oldString, newString, structuredPatch, ...}
503	func enrichToolResults(results []toolResultEntry, tur map[string]json.RawMessage) []toolResultEntry {
504		// Bash-style: stdout provides the output text.
505		if stdout := unquote(tur["stdout"]); stdout != "" {
506			switch len(results) {
507			case 0:
508				// Keep compatibility with transcripts that only include toolUseResult.
509				results = append(results, toolResultEntry{output: stdout})
510			case 1:
511				results[0].output = stdout
512			}
513		}
514	
515		// Read-style: file object with filePath and numLines.
516		if fileRaw, ok := tur["file"]; ok {
517			var file struct {
518				FilePath string `json:"filePath"`
519				NumLines int    `json:"numLines"`
520			}
521			if json.Unmarshal(fileRaw, &file) == nil && file.FilePath != "" {
522				applyToSingleResult(results, func(tr *toolResultEntry) {
523					tr.file = &toolResultFile{filePath: file.FilePath, numLines: file.NumLines}
524				})
525			}
526		}
527	
528		// Edit-style: top-level filePath.
529		if filePath := unquote(tur["filePath"]); filePath != "" {
530			applyToSingleResult(results, func(tr *toolResultEntry) {
531				// Edit results don't have numLines.
532				tr.file = &toolResultFile{filePath: filePath}
533			})
534		}
535	
536		// Grep-style: numFiles as match count.
537		if numFilesRaw, ok := tur["numFiles"]; ok {
538			var n int
539			if json.Unmarshal(numFilesRaw, &n) == nil && n > 0 {
540				applyToSingleResult(results, func(tr *toolResultEntry) {
541					tr.matchCount = n
542				})
543			}
544		}
545	
546		return results
547	}
