// mapping so callers don't depend on which agent packages are linked in;
// dynamically registered (external) agents fall back to a registry lookup.
func NameForAgentType(agentType types.AgentType) (types.AgentName, bool) {
	if name, ok := builtinAgentNamesByType[agentType]; ok {
		return name, true
	}
