func (s *GitStore) writeCompactTranscript(ctx context.Context, opts WriteCommittedOptions, basePath string, transcriptBytes []byte, entries map[string]object.TreeEntry) {
	compacted, err := transcriptcompact.Compact(redact.AlreadyRedacted(transcriptBytes), transcriptcompact.MetadataFields{
		Agent:      compactAgentName(opts.Agent),
		CLIVersion: versioninfo.Version,
	})
	if err == nil && len(compacted) == 0 {
		return
	}

